package com.mohymods.kingdomsmp.profession;
import static org.junit.jupiter.api.Assertions.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.io.TempDir;
import java.nio.file.*;
import java.io.IOException;
class SmithRulesTest {
 @TempDir Path dir;
 @Test void oldSixContractFileRemainsExactAndNewSmithDefaultsAreAdditive()throws Exception{var p=dir.resolve("contracts.json");ContractRules.load(p);var json=com.google.gson.JsonParser.parseString(Files.readString(p)).getAsJsonObject();json.getAsJsonObject("deliveries").remove("blacksmith/daily");json.getAsJsonObject("deliveries").remove("blacksmith/weekly");for(var role:Profession.values())if(!java.util.Set.of(Profession.FARMER,Profession.BUILDER,Profession.LUMBERJACK).contains(role)){json.getAsJsonObject("deliveries").remove(role.id()+"/daily");json.getAsJsonObject("deliveries").remove(role.id()+"/weekly");}Files.writeString(p,json.toString());String before=Files.readString(p);var rules=ContractRules.load(p);assertEquals(24,rules.all().size());assertEquals(16,rules.get("blacksmith/daily").quantity());assertEquals(160,rules.get("blacksmith/daily").reward());assertEquals(before,Files.readString(p));json.getAsJsonObject("deliveries").remove("farmer/daily");Files.writeString(p,json.toString());assertThrows(IOException.class,()->ContractRules.load(p));}
 @Test void repairGoalsHaveBoundedExplicitDefaultsAndNeverRewriteCustomRules()throws Exception{var p=dir.resolve("repairs.json");assertEquals(4,RepairQuestRules.load(p));Files.writeString(p,"{\"schema\":1,\"distinctIronItems\":6}");String before=Files.readString(p);assertEquals(6,RepairQuestRules.load(p));assertEquals(before,Files.readString(p));for(String n:new String[]{"0","129","1.5","\"4\""}){Files.writeString(p,"{\"schema\":1,\"distinctIronItems\":"+n+"}");assertThrows(IOException.class,()->RepairQuestRules.load(p));}}
 @Test void oldRepairRulesNeverInventEnchantedHistoryOrRewriteBytesAndNewCountsAreBounded()throws Exception{var p=dir.resolve("repair-bands.json");Files.writeString(p,"{\"schema\":1,\"distinctIronItems\":7}");var bytes=Files.readString(p);var g=RepairQuestRules.loadGoals(p);assertEquals(7,g.ordinary());assertEquals(4,g.enchanted());assertEquals(4,g.tools());assertEquals(1,g.upgrades());assertEquals(bytes,Files.readString(p));for(String n:new String[]{"0","129","1.5","\"4\""}){Files.writeString(p,"{\"schema\":1,\"distinctIronItems\":4,\"enchantedIronItems\":4,\"enchantedTools\":"+n+"}");assertThrows(IOException.class,()->RepairQuestRules.loadGoals(p));}}

 @Test void smithingAllowsOnlyMatchingOrdinaryNativeDiamondTransforms(){for(var type:java.util.List.of("pickaxe","axe","shovel","hoe","sword","helmet","chestplate","leggings","boots"))assertTrue(SmithingQuestService.pair("minecraft:diamond_"+type,"minecraft:netherite_"+type));assertFalse(SmithingQuestService.pair("minecraft:diamond_pickaxe","minecraft:netherite_axe"));assertFalse(SmithingQuestService.pair("minecraft:iron_pickaxe","minecraft:netherite_pickaxe"));assertFalse(SmithingQuestService.pair("foreign:diamond_pickaxe","minecraft:netherite_pickaxe"));assertFalse(SmithingQuestService.upgraded("minecraft:netherite_ingot"));assertFalse(SmithingQuestService.upgraded("foreign:netherite_pickaxe"));}

 @Test void authenticatedOutputGoalsCannotExceedPhysicalInventoryCapacity()throws Exception{var p=dir.resolve("native-output-capacity.json");Files.writeString(p,"{\"schema\":1,\"distinctIronItems\":128,\"enchantedIronItems\":128,\"enchantedTools\":36,\"netheriteUpgrades\":36}");assertEquals(36,RepairQuestRules.loadGoals(p).tools());assertEquals(36,RepairQuestRules.loadGoals(p).upgrades());Files.writeString(p,Files.readString(p).replace(":36",":37"));assertThrows(IOException.class,()->RepairQuestRules.loadGoals(p));}

}
